function newQueueId() {
  return `q${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

// Places one group of players (a full team, or a single solo player) into
// queues as one FCFS unit: fills the first existing queue that has room
// for the *whole* group before opening a new queue. A team is never split
// across two queues, and no empty placeholder queue is created unless
// nothing has room.
function enqueueGroup(group, queuesList, makeQueueId) {
  if (!group || group.length === 0) return queuesList;
  const target = queuesList.find(
    (q) => (q.players || []).length + group.length <= 4
  );
  if (target) {
    return queuesList.map((q) =>
      q.id === target.id ? { ...q, players: [...q.players, ...group] } : q
    );
  }
  return [...queuesList, { id: makeQueueId(), players: group }];
}

// Groups a flat list of players by team_id (players with no team_id are
// each their own solo group of 1) and enqueues each group in turn, FCFS,
// via enqueueGroup. Keeps teammates together instead of scattering them
// one-by-one.
function enqueuePlayersGrouped(playersList, queuesList, makeQueueId) {
  let next = queuesList;
  const seen = new Set();
  for (const p of playersList) {
    if (seen.has(p.id)) continue;
    if (p.team_id) {
      const teammates = playersList.filter((x) => x.team_id === p.team_id);
      teammates.forEach((t) => seen.add(t.id));
      next = enqueueGroup(teammates, next, makeQueueId);
    } else {
      seen.add(p.id);
      next = enqueueGroup([p], next, makeQueueId);
    }
  }
  return next;
}

export default function DashboardPage() {
  const router = useRouter();
  const [session, setSessionState] = useState(null);
  const [courts, setCourts] = useState([]);
  const [queues, setQueues] = useState([]);
  const [duration, setDuration] = useState(20);
  const [requests, setRequests] = useState([]); // admin: all pending requests
  const [myRequest, setMyRequest] = useState(null); // player: own pending request, or null
  const [players, setPlayers] = useState([]);
  const [loadingPlayers, setLoadingPlayers] = useState(true);
  const [ready, setReady] = useState(false);
  const [playersError, setPlayersError] = useState("");
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [autoPlayIn, setAutoPlayIn] = useState(null);
  const [autoDuration, setAutoDuration] = useState(true);
  const [timeMode, setTimeMode] = useState("shared");

  // Tracks in-flight saveQueues() calls so an incoming realtime snapshot
  // doesn't stomp on a local optimistic update that hasn't landed yet.
  const pendingQueueWrites = useRef(0);
  const pendingDurationWrite = useRef(0);

  useEffect(() => {
    const savedMode = window.localStorage.getItem("timeMode");
    if (savedMode === "shared" || savedMode === "perCourt") {
      setTimeMode(savedMode);
    }
  }, []);
  const [editingProfile, setEditingProfile] = useState(false);
  const activeCourts = courts.filter((c) => c.active !== false);
  const [announcement, setAnnouncement] = useState("");
  const courtsEmpty = courts.every((c) => !c.running && (c.players || []).length === 0);
  const fullQueueCount = queues.filter((q) => q.players.length === 4).length;
  const canPlay =
    courtsEmpty &&
    activeCourts.length > 0 &&
    fullQueueCount >= activeCourts.length;

  const refreshPlayers = useCallback(async () => {
    setLoadingPlayers(true);
    try {
      const data = await getAllPlayers();
      setPlayers(data);
      setPlayersError("");
    } catch (err) {
      setPlayersError(err.message);
    }
    setLoadingPlayers(false);
  }, []);

useEffect(() => {
  const s = getSession();
  if (!s) {
    router.replace("/login");
    return;
  }
  setSessionState(s);
  refreshPlayers();

  const unsubscribePlayers = subscribeToPlayers(refreshPlayers);

  (async () => {
    try {
      const state = await getAppState();
      setCourts(state.courts || []);
      setQueues(state.queues || []);
      setDuration(state.duration ?? 20);
      setAutoDuration(state.auto_duration ?? true);
      setAnnouncement(state.announcement || "");
    } catch (err) {
      setPlayersError(err.message);
    }
    setReady(true);
  })();

const unsubscribe = subscribeToAppState((newState) => {
  if (newState.courts) setCourts(newState.courts);
  if (newState.queues && pendingQueueWrites.current === 0) {
    setQueues(newState.queues);
  }
  if (newState.duration != null && pendingDurationWrite.current === 0) {
    setDuration(newState.duration);
  }
if (newState.auto_duration != null && pendingDurationWrite.current === 0) {
  setAutoDuration(newState.auto_duration);
}  if (newState.announcement !== undefined) setAnnouncement(newState.announcement);
});

  return () => {
    unsubscribe();
    unsubscribePlayers();
  };
}, [router, refreshPlayers]);

  // Live-updates player rows (present/absent, team assignment, etc.) so
// changes made by the admin — including direct toggles that don't go
// through the request flow — show up on every device without a refresh.
useEffect(() => {
  if (!session) return;

  const channel = supabase
    .channel("players_changes")
    .on(
      "postgres_changes",
      { event: "*", schema: "public", table: "players" },
      () => refreshPlayers()
    )
    .subscribe();

  return () => supabase.removeChannel(channel);
}, [session, refreshPlayers]);

function playBuzzer() {
  const audio = new Audio("/sounds/alarm.mp3");
  audio.volume = 0.8;
  
  audio.play().then(() => {
    setTimeout(() => {
      audio.pause();
      audio.currentTime = 0;
    }, 10000); // 10,000 ms = 10 seconds
  }).catch(() => {});
}

function handleTimeModeChange(mode) {
  setTimeMode(mode);
  window.localStorage.setItem("timeMode", mode);
}

  // Always builds the next value from the latest state (via the updater
  // function form of setState), never from a closed-over `queues`
  // variable. This is what prevents two near-simultaneous queue actions
  // (e.g. approving two requests back to back, or a double click) from
  // clobbering each other.
  function persistQueues(updater) {
    setQueues((prev) => {
      const next = typeof updater === "function" ? updater(prev) : updater;
      pendingQueueWrites.current++;
      saveQueues(next)
        .catch((err) => setPlayersError(err.message))
        .finally(() => {
          pendingQueueWrites.current--;
        });
      return next;
    });
  }

  function persistCourts(next) {
    setCourts(next);
    saveCourts(next).catch((err) => setPlayersError(err.message));
  }

  function handleToggleCourtActive(courtId) {
    const nextCourts = courts.map((c) =>
      c.id === courtId ? { ...c, active: c.active === false ? true : false } : c
    );
    persistCourts(nextCourts);
  } 

  function getAvailable(playersList, queuesList, courtsList) {
    const queuedIds = new Set(
      queuesList.flatMap((q) => (q.players || []).filter(Boolean).map((p) => p.id))
    );
    const onCourtIds = new Set(
      courtsList.flatMap((c) => (c.players || []).filter(Boolean).map((p) => p.id))
    );
    return playersList.filter(
      (p) => p.present && !queuedIds.has(p.id) && !onCourtIds.has(p.id)
    );
  }

  // Start a single court using the first full queue available
function handlePlayCourt(courtId) {
  const targetCourt = courts.find((c) => c.id === courtId);
  if (!targetCourt || targetCourt.active === false || targetCourt.running) return;

  const firstFullQueue = queues.find((q) => q.players.length === 4);
  if (!firstFullQueue) return;

  const courtDuration =
    timeMode === "perCourt" ? (targetCourt.duration ?? duration) : duration;

  const nextCourts = courts.map((c) =>
    c.id === courtId
      ? {
          ...c,
          players: firstFullQueue.players.map((p) => ({ id: p.id, name: p.name })),
          queueLabel: "Active Queue",
          endsAt: Date.now() + courtDuration * 60 * 1000,
          running: true,
        }
      : c
  );

  persistCourts(nextCourts);
  persistQueues((prevQueues) => prevQueues.filter((q) => q.id !== firstFullQueue.id));
}

// Finish a single court and re-queue its players
function handleMatchFinishedCourt(courtId) {
  const court = courts.find((c) => c.id === courtId);
  if (!court || (court.players || []).length === 0) return;

  const nextCourts = courts.map((c) =>
    c.id === courtId
      ? { ...c, players: [], queueLabel: null, endsAt: null, running: false }
      : c
  );
  persistCourts(nextCourts);

  persistQueues((prevQueues) => {
    // Guard against this handler firing twice for the same match finish
    // (double-click on Finish, a fast double-tap, etc.). Since
    // persistCourts/persistQueues are async, a second call can still see
    // the same court.players and would otherwise enqueue them again.
    const alreadyQueuedIds = new Set(
      prevQueues.flatMap((q) => (q.players || []).map((p) => p.id))
    );
    const freedPresent = court.players
      .filter((freed) => !alreadyQueuedIds.has(freed.id))
      .map((freed) => players.find((p) => p.id === freed.id))
      .filter((p) => p && p.present);

    // Re-queue as whole teams (or solo players) so a team of 4/3/2 goes
    // back into one queue together, filling an existing partial queue
    // first-come-first-served instead of scattering into new/empty ones.
    return enqueuePlayersGrouped(freedPresent, prevQueues, newQueueId);
  });
}

  async function handleToggleSuspendPlayer(player, suspended) {
    // Optimistically update local state
    const updatedPlayers = players.map((p) =>
      p.id === player.id ? { ...p, suspended, present: suspended ? false : p.present } : p
    );
    setPlayers(updatedPlayers);

    // If suspended, remove player from queues immediately
    if (suspended) {
      persistQueues((prevQueues) =>
        prevQueues.map((q) => ({
          ...q,
          players: q.players.filter((p) => p.id !== player.id),
        }))
      );
    }

    try {
      await setPlayerSuspended(player.id, suspended);
      if (suspended) {
        await setPlayerPresent(player.id, false);
      }
    } catch (err) {
      setPlayersError(err.message);
    }
  }

  async function handleSaveAnnouncement(newAnnouncement) {
  setAnnouncement(newAnnouncement);
  try {
    await saveAnnouncement(newAnnouncement);
  } catch (err) {
    setPlayersError(err.message);
  }
}

  async function handleTogglePresent(player) {
    const nextPresent = !player.present;
    const updatedPlayers = players.map((p) =>
      p.id === player.id ? { ...p, present: nextPresent } : p
    );
    setPlayers(updatedPlayers);

    try {
      await setPlayerPresent(player.id, nextPresent);
    } catch (err) {
      setPlayersError(err.message);
    }

    if (!nextPresent) {
      persistQueues((prevQueues) =>
        prevQueues.map((q) => ({
          ...q,
          players: q.players.filter((p) => p.id !== player.id),
        }))
      );
    }
  }

  async function handleMarkAllAbsent() {
    const confirmed = window.confirm(
      "Are you sure you want to mark ALL present players as absent?"
    );
    if (!confirmed) return;

    const presentPlayers = players.filter((p) => p.present);
    if (presentPlayers.length === 0) return;

    // Optimistically set all players as absent locally
    const updatedPlayers = players.map((p) => ({ ...p, present: false }));
    setPlayers(updatedPlayers);

    // Clear queues
    persistQueues(() => []);

    // Update backend
    try {
      await Promise.all(
        presentPlayers.map((p) => setPlayerPresent(p.id, false))
      );
    } catch (err) {
      setPlayersError(err.message);
    }
  }

  // Accepts an optional queues list to check against so callers can verify
  // membership against a freshly-read `prevQueues` inside a persistQueues
  // updater, instead of a possibly-stale closed-over `queues`.
  function isPlayerQueuedOrPlaying(playerId, queuesList = queues) {
    const onCourt = courts.some((c) => (c.players || []).some((p) => p.id === playerId));
    const inQueue = queuesList.some((q) => (q.players || []).some((p) => p.id === playerId));
    return onCourt || inQueue;
  }

  function handleQueuePlayer(player) {
    persistQueues((prevQueues) => {
      if (isPlayerQueuedOrPlaying(player.id, prevQueues)) return prevQueues;
      return assignPresentPlayer(player, prevQueues, players, newQueueId);
    });
  }

  function handleQueueTeam(teamId) {
    persistQueues((prevQueues) => {
      const teammates = players.filter(
        (p) => p.team_id === teamId && p.present && !isPlayerQueuedOrPlaying(p.id, prevQueues)
      );
      if (teammates.length === 0) return prevQueues;
      // Fill the first existing queue with room for the whole team before
      // opening a new one (FCFS), instead of always creating a new queue.
      return enqueueGroup(teammates, prevQueues, newQueueId);
    });
  }

  function handleRequestPresent(player) {
    setMyRequest({
      id: "pending",
      player_id: player.id,
      player_name: player.name,
      type: "presence",
      team_id: null,
      created_at: new Date().toISOString(),
    });
    createPresenceRequest(player.id, player.name).catch((err) => {
      setPlayersError(err.message);
      setMyRequest(null);
    });
  }

  function handleRequestCreateTeam(player, teamName) {
    const chosenName = teamName?.trim() || "Team";
    setMyRequest({
      id: "pending",
      player_id: player.id,
      player_name: player.name,
      type: "team_create",
      team_id: chosenName,
      created_at: new Date().toISOString(),
    });
    createTeamCreateRequest(player.id, player.name, chosenName).catch((err) => {
      setPlayersError(err.message);
      setMyRequest(null);
    });
  }

  function handleRequestJoinTeam(player, teamId) {
    setMyRequest({
      id: "pending",
      player_id: player.id,
      player_name: player.name,
      type: "team_join",
      team_id: teamId,
      created_at: new Date().toISOString(),
    });
    createTeamJoinRequest(player.id, player.name, teamId).catch((err) => {
      setPlayersError(err.message);
      setMyRequest(null);
    });
  }

  function handleCancelRequest(player) {
    setMyRequest(null);
    cancelRequest(player.id).catch((err) => setPlayersError(err.message));
  }

  // Approving any request type (presence, team create, team join) marks the
  // player present and auto-queues them — but only if they aren't already
  // queued/playing, to avoid placing them into a second queue. The
  // queued/playing check and the actual queue insert both happen inside
  // the persistQueues updater so they run against the same, freshest
  // queues snapshot even if another approval is racing this one.
  function handleApproveRequest(request) {
    setRequests((prev) => prev.filter((r) => r.id !== request.id));
    resolveRequest(request.id).catch((err) => setPlayersError(err.message));

    const player = players.find((p) => p.id === request.player_id);
    if (!player) return;

    let updatedPlayer = { ...player, present: true };

    if (request.type === "team_create") {
      const chosenLabel = request.team_id || "Team";
      updatedPlayer.team_id = chosenLabel;
      setPlayerTeam(player.id, chosenLabel).catch((err) => setPlayersError(err.message));
    } else if (request.type === "team_join") {
      updatedPlayer.team_id = request.team_id;
      setPlayerTeam(player.id, request.team_id).catch((err) => setPlayersError(err.message));
    }

    const updatedPlayers = players.map((p) => (p.id === player.id ? updatedPlayer : p));
    setPlayers(updatedPlayers);
    if (!player.present) {
      setPlayerPresent(player.id, true).catch((err) => setPlayersError(err.message));
    }

    if (request.type !== "team_create" && request.type !== "team_join") {
      persistQueues((prevQueues) => {
        if (isPlayerQueuedOrPlaying(player.id, prevQueues)) return prevQueues;
        return assignPresentPlayer(updatedPlayer, prevQueues, updatedPlayers, newQueueId);
      });
    }
  }

  function handleDenyRequest(requestId) {
    setRequests((prev) => prev.filter((r) => r.id !== requestId));
    resolveRequest(requestId).catch((err) => setPlayersError(err.message));
  }

  async function handleSetPlayerTeam(playerId, teamId) {
    setPlayers((prev) =>
      prev.map((p) => (p.id === playerId ? { ...p, team_id: teamId || null } : p))
    );

    try {
      await setPlayerTeam(playerId, teamId);
    } catch (err) {
      setPlayersError(err.message);
    }
  }

  function handleDeleteTeam(teamId, members) {
    const memberIds = new Set(members.map((m) => m.id));
    setPlayers((prev) =>
      prev.map((p) => (memberIds.has(p.id) ? { ...p, team_id: null } : p))
    );
    for (const m of members) {
      setPlayerTeam(m.id, "").catch((err) => setPlayersError(err.message));
    }
  }

  function handleAddPlayerToTeam(teamId, playerId) {
    handleSetPlayerTeam(playerId, teamId);
  }

  function handleRemovePlayerFromTeam(playerId) {
    handleSetPlayerTeam(playerId, "");
  }

  function handleLeaveTeamSelf(player) {
    handleSetPlayerTeam(player.id, "");
  }

  function handleRemovePlayerFromQueue(queueId, playerId) {
    persistQueues((prevQueues) =>
      prevQueues.map((q) =>
        q.id === queueId
          ? { ...q, players: q.players.filter((p) => p.id !== playerId) }
          : q
      )
    );
  }

  function handleAddPlayerToQueue(queueId, player) {
    persistQueues((prevQueues) => {
      if (isPlayerQueuedOrPlaying(player.id, prevQueues)) return prevQueues;
      return prevQueues.map((q) =>
        q.id === queueId && q.players.length < 4
          ? { ...q, players: [...q.players, player] }
          : q
      );
    });
  }

  function handleDeleteQueue(queueId) {
    persistQueues((prevQueues) => prevQueues.filter((q) => q.id !== queueId));
  }

  function handleAddQueue() {
    persistQueues((prevQueues) => [...prevQueues, { id: newQueueId(), players: [] }]);
  }

function handlePlay() {
  const activeList = courts.filter((c) => c.active !== false);
  if (activeList.length === 0) return;

  const fullQueues = queues.filter((q) => q.players.length === 4);
  if (fullQueues.length < activeList.length) return;

  const queuesToPlay = fullQueues.slice(0, activeList.length);
  const playIds = new Set(queuesToPlay.map((q) => q.id));

  let queueIndex = 0;
  const nextCourts = courts.map((court) => {
    if (court.active === false) return court;

    const q = queuesToPlay[queueIndex];
    queueIndex++;

    const courtDuration =
      timeMode === "perCourt" ? court.duration ?? duration : duration;

    return {
      ...court,
      players: q.players.map((p) => ({ id: p.id, name: p.name })),
      queueLabel: `Queue ${queueIndex}`,
      endsAt: Date.now() + courtDuration * 60 * 1000,
      running: true,
    };
  });

  persistCourts(nextCourts);
  persistQueues((prevQueues) => prevQueues.filter((q) => !playIds.has(q.id)));
}

  function handleMatchFinished() {
    const playingCourts = courts.filter((c) => c.players.length > 0);
    if (playingCourts.length === 0) return;

    const nextCourts = courts.map((c) =>
      c.players.length > 0
        ? { ...c, players: [], queueLabel: null, endsAt: null, running: false }
        : c
    );
    persistCourts(nextCourts);

    persistQueues((prevQueues) => {
      const alreadyQueuedIds = new Set(
        prevQueues.flatMap((q) => (q.players || []).map((p) => p.id))
      );
      const freedPresent = playingCourts
        .flatMap((c) => c.players)
        .filter((freed) => !alreadyQueuedIds.has(freed.id))
        .map((freed) => players.find((p) => p.id === freed.id))
        .filter((p) => p && p.present);

      // Re-queue as whole teams (or solo players), FCFS into the first
      // queue with room, instead of one player at a time.
      return enqueuePlayersGrouped(freedPresent, prevQueues, newQueueId);
    });
  }

function handleDurationChange(minutes, manual = true) {
  if (manual) setAutoDuration(false);
  setDuration(minutes);
  pendingDurationWrite.current++;
  const save = manual ? saveDurationManual(minutes) : saveDuration(minutes);
  save
    .catch((err) => setPlayersError(err.message))
    .finally(() => {
      pendingDurationWrite.current--;
    });
}
  function handleCourtDurationChange(courtId, minutes) {
  const nextCourts = courts.map((c) =>
    c.id === courtId ? { ...c, duration: minutes } : c
  );
  persistCourts(nextCourts);
}
  // Counts full (4-player) courts and full (4-player) queues — i.e. complete
  // teams currently playing or waiting to play. Partially-filled queues
  // don't count.
  function countFullTeams(courtsList, queuesList) {
    const courtTeams = courtsList.filter((c) => (c.players || []).length === 4).length;
    const queueTeams = queuesList.filter((q) => (q.players || []).length === 4).length;
    return courtTeams + queueTeams;
  }
  function handleLogout() {
    logout();
    router.replace("/login");
  }

  const isAdmin = session?.role === "admin";
  const currentPlayer = session ? players.find((p) => p.id === session.id) : null;
  const showSidebar = (isAdmin && sidebarOpen) || (!isAdmin && !!currentPlayer);
  const currentPlayerId = currentPlayer?.id ?? null;

  // Requests are scoped per-role: admin subscribes to every pending request,
  // a player only ever fetches/subscribes to their own single row so other
  // players' requests never reach their client.
  useEffect(() => {
    if (!session) return;

    if (isAdmin) {
      let cancelled = false;
      const refresh = () =>
        getAllRequests()
          .then((data) => {
            if (!cancelled) setRequests(data);
          })
          .catch((err) => setPlayersError(err.message));

      refresh();
      const unsubscribe = subscribeToAllRequests(refresh);
      return () => {
        cancelled = true;
        unsubscribe();
      };
    }

    if (currentPlayerId) {
      let cancelled = false;
      const refresh = () =>
        getOwnRequest(currentPlayerId)
          .then((data) => {
            if (!cancelled) setMyRequest(data);
          })
          .catch((err) => setPlayersError(err.message));

refresh();
const unsubscribe = subscribeToOwnRequest(currentPlayerId, () => {
  refresh();
  refreshPlayers();
});
return () => {
  cancelled = true;
  unsubscribe();
};
}
}, [session, isAdmin, currentPlayerId, refreshPlayers]);

  // Auto match length: 6 full teams (courts + queues combined) -> 20m,
  // 7+ -> 15m. Only applies while autoDuration is on; a manual change via
  // handleDurationChange turns it off so the admin's choice sticks.
  useEffect(() => {
    if (!isAdmin || !autoDuration) return;
    const totalTeams = countFullTeams(courts, queues);
    const target = totalTeams >= 7 ? 15 : 20;
    if (target !== duration) {
      handleDurationChange(target, false);
    }
  }, [isAdmin, autoDuration, courts, queues]);


  // Auto "Match finished": check per court
useEffect(() => {
  if (!isAdmin) return;
  const interval = setInterval(() => {
    const expiredCourts = courts.filter(
      (c) => c.running && c.endsAt && Date.now() >= c.endsAt
    );
    if (expiredCourts.length > 0) {
      playBuzzer();
      if (timeMode === "perCourt") {
        expiredCourts.forEach((c) => handleMatchFinishedCourt(c.id));
      } else {
        handleMatchFinished();
      }
    }
  }, 1000);
  return () => clearInterval(interval);
}, [isAdmin, courts, queues, players, timeMode]);

  // Auto "Play": once queues 1-3 are full (canPlay), wait 1 minute then
  // trigger the same logic the button does, unless it stops being ready
  // before the minute is up. Button stays visible.
  

  useEffect(() => {
    if (!isAdmin || !canPlay || !courtsEmpty) {
      setAutoPlayIn(null);
      return;
    }
    const target = Date.now() + 60 * 1000;
    setAutoPlayIn(60);

    const tick = setInterval(() => {
      const secsLeft = Math.max(0, Math.ceil((target - Date.now()) / 1000));
      setAutoPlayIn(secsLeft);
    }, 1000);

    const timeout = setTimeout(() => {
      handlePlay();
    }, 60 * 1000);

    return () => {
      clearInterval(tick);
      clearTimeout(timeout);
    };
  }, [isAdmin, canPlay, courtsEmpty, queues, courts, duration]);

  if (!ready) return null;

  const available = getAvailable(players, queues, courts);
  const statusMap = {};
  for (const c of courts) {
    for (const p of c.players || []) {
      if (p) statusMap[p.id] = "playing";
    }
  }
  for (const q of queues) {
    for (const p of q.players || []) {
      if (p && !statusMap[p.id]) statusMap[p.id] = "queued";
    }
  }
  const nextToPlayIds = new Set(
    queues.slice(0, 3).flatMap((q) => (q.players || []).filter(Boolean).map((p) => p.id))
  );
  const myStatus = session
    ? statusMap[session.id] === "playing"
      ? "playing"
      : nextToPlayIds.has(session.id)
      ? "next"
      : null
    : null;

  return (
    <main className="min-h-screen bg-[var(--background)]">
      <header className="border-b border-[var(--border)] bg-[var(--surface)]">
        <div className="max-w-6xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-[var(--yellow)]" />
            <h1 className="font-semibold tracking-tight">Miagao Pickleball Club</h1>
          </div>
          <div className="flex items-center gap-4">
            <button
  onClick={() => setEditingProfile(true)}
  className="text-sm text-gray-500 hover:text-[var(--blue)] font-medium transition-colors"
>
  {formatPlayerName(session?.name)}
</button>
            <button onClick={handleLogout} className="text-sm text-[var(--blue)] font-medium">
              Log out
            </button>
          </div>
        </div>
      </header>

      {myStatus === "playing" && (
        <div className="bg-green-600 text-white text-sm font-medium text-center py-2 px-4">
          You're currently playing, {formatPlayerName(session?.name)}
        </div>
      )}
      {myStatus === "next" && (
        <div className="bg-red-600 text-white text-sm font-medium text-center py-2 px-4">
          You're next to play, {formatPlayerName(session?.name)}
        </div>
      )}

      <div
        className={`max-w-6xl mx-auto px-4 py-8 grid grid-cols-1 gap-8 ${
          showSidebar ? "lg:grid-cols-[1fr_280px]" : "lg:grid-cols-1"
        }`}
      >
        <div className="space-y-8">
          {/* Announcement banner visible to players and editable by admin */}
          <AnnouncementBanner
            announcement={announcement}
            isAdmin={isAdmin}
            onSaveAnnouncement={handleSaveAnnouncement}
          />
                  
          <section>
  <div className="flex items-center justify-between mb-3">
    <h2 className="text-sm font-medium text-gray-500 uppercase tracking-wide">
      Courts
    </h2>
    <div className="flex items-center gap-3">
      {/* Show the global 'Match finished' button ONLY in Shared mode */}
      {isAdmin && timeMode === "shared" && (
        <button
          onClick={handleMatchFinished}
          disabled={!courts.some((c) => c.players.length > 0)}
          className="text-sm text-[var(--blue)] font-medium disabled:opacity-40 disabled:cursor-not-allowed"
        >
          Match finished
        </button>
      )}
      {isAdmin && (
        <button
          onClick={() => setSidebarOpen((o) => !o)}
          className="text-sm text-gray-400 hover:text-[var(--blue)] font-medium"
          title={sidebarOpen ? "Hide panel" : "Show panel"}
        >
          {sidebarOpen ? "› Hide panel" : "‹ Show panel"}
        </button>
      )}
    </div>
  </div>

  {isAdmin && timeMode === "perCourt" && (
    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-2">
      {courts.map((court) => (
        <div key={court.id} className="flex items-center gap-2 text-sm">
          <span className="text-gray-500">{court.name || court.id}:</span>
          <input
            type="number"
            min="1"
            value={court.duration ?? duration}
            onChange={(e) =>
              handleCourtDurationChange(court.id, Number(e.target.value) || 1)
            }
            className="w-16 px-2 py-1 border border-[var(--border)] rounded text-center"
          />
          <span className="text-gray-400">m</span>
        </div>
      ))}
    </div>
  )}

  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
    {courts.map((court) => {
      const isCourtAvailable =
        court.active !== false &&
        !court.running &&
        (court.players || []).length === 0;
      const hasFullQueue = queues.some((q) => (q.players || []).length === 4);

      return (
        <CourtCard
          key={court.id}
          court={court}
          isAdmin={isAdmin}
          timeMode={timeMode}
          canPlayCourt={isCourtAvailable && hasFullQueue}
          onPlay={() => handlePlayCourt(court.id)}
          onFinish={() => handleMatchFinishedCourt(court.id)}
          onToggleActive={handleToggleCourtActive}
        />
      );
    })}
  </div>
</section>
<section>
            {isAdmin && (
              <div className="flex flex-wrap items-center justify-between gap-3 mb-3">
                {/* Match length & Auto/Manual: Only visible when NOT in per-court mode */}
                {timeMode === "shared" && (
                  <div className="flex items-center gap-2">
                    <label className="text-sm text-gray-500">Match length</label>

                    {/* Duration Buttons & Input (Disabled when in Auto mode) */}
                    <div
                      className={`flex items-center rounded-lg border border-[var(--border)] overflow-hidden transition-opacity ${
                        autoDuration
                          ? "opacity-50 pointer-events-none bg-gray-50"
                          : "opacity-100"
                      }`}
                    >
                      {[15, 20].map((mins) => (
                        <button
                          key={mins}
                          type="button"
                          onClick={() => handleDurationChange(mins, true)}
                          className={`px-3 py-1 text-sm font-medium transition-colors ${
                            duration === mins
                              ? "bg-[var(--blue)] text-white"
                              : "bg-white text-gray-600 hover:bg-gray-50"
                          }`}
                        >
                          {mins}m
                        </button>
                      ))}
                      <input
                        type="number"
                        min="1"
                        value={duration}
                        onChange={(e) =>
                          handleDurationChange(Number(e.target.value) || 1, true)
                        }
                        className="w-16 px-2 py-1 text-sm border-l border-[var(--border)] bg-transparent text-center focus:outline-none"
                      />
                    </div>

                    {/* Auto / Manual Toggle */}
                    <div className="flex items-center rounded-lg border border-[var(--border)] overflow-hidden">
                      <button
                        type="button"
                        onClick={() => {
  setAutoDuration(true);
  saveAutoDuration(true).catch((err) => setPlayersError(err.message));
}}
                        title="Auto: 7+ full teams (courts + queues) -> 15m, else 20m"
                        className={`px-3 py-1 text-sm font-medium transition-colors ${
                          autoDuration
                            ? "bg-[var(--blue)] text-white"
                            : "bg-white text-gray-600 hover:bg-gray-50"
                        }`}
                      >
                        Auto
                      </button>
                      <button
                        type="button"
                        onClick={() => {
  setAutoDuration(false);
  saveAutoDuration(false).catch((err) => setPlayersError(err.message));
}}
                        className={`px-3 py-1 text-sm font-medium border-l border-[var(--border)] transition-colors ${
                          !autoDuration
                            ? "bg-[var(--blue)] text-white"
                            : "bg-white text-gray-600 hover:bg-gray-50"
                        }`}
                      >
                        Manual
                      </button>
                    </div>
                  </div>
                )}

                {/* Shared vs Per Court Mode Toggle */}
                <div className="flex items-center rounded-lg border border-[var(--border)] overflow-hidden">
                  <button
                    type="button"
                    onClick={() => handleTimeModeChange("shared")}
                    className={`px-3 py-1 text-sm font-medium transition-colors ${
                      timeMode === "shared"
                        ? "bg-[var(--blue)] text-white"
                        : "bg-white text-gray-600 hover:bg-gray-50"
                    }`}
                  >
                    Shared
                  </button>
                  <button
                    type="button"
                    onClick={() => handleTimeModeChange("perCourt")}
                    className={`px-3 py-1 text-sm font-medium border-l border-[var(--border)] transition-colors ${
                      timeMode === "perCourt"
                        ? "bg-[var(--blue)] text-white"
                        : "bg-white text-gray-600 hover:bg-gray-50"
                    }`}
                  >
                    Per court
                  </button>
                </div>

                {/* Global Play Button: Only visible in shared mode */}
                {timeMode === "shared" && (
                  <div className="flex items-center gap-2">
                    <button
                      onClick={handlePlay}
                      disabled={!canPlay}
                      className="rounded-lg bg-[var(--blue)] text-white font-medium text-sm px-5 py-2 hover:bg-[var(--blue-dark)] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
                    >
                      ▶ Play
                    </button>
                    {autoPlayIn != null && (
                      <span className="text-xs text-gray-400">
                        Automatically starts in {autoPlayIn}s
                      </span>
                    )}
                  </div>
                )}
              </div>
            )}

            <QueueBoard
              queues={queues}
              availablePlayers={available}
              onRemovePlayer={handleRemovePlayerFromQueue}
              onAddPlayer={handleAddPlayerToQueue}
              onDeleteQueue={handleDeleteQueue}
              onAddQueue={handleAddQueue}
              readOnly={!isAdmin}
            />
          </section>
        </div>

        {isAdmin && sidebarOpen && (
          <aside className="space-y-4">
            {playersError && (
              <p className="text-sm text-red-600 mb-3">{playersError}</p>
            )}

            <RequestsPanel
              requests={requests}
              onApprove={handleApproveRequest}
              onDeny={handleDenyRequest}
            />

            <PresentPanel
              players={players}
              statusMap={statusMap}
              onTogglePresent={handleTogglePresent}
              onQueuePlayer={handleQueuePlayer}
              onMarkAllAbsent={handleMarkAllAbsent}
              loading={loadingPlayers}
              onAddPlayerToTeam={handleAddPlayerToTeam}
              onRemovePlayerFromTeam={handleRemovePlayerFromTeam}
              onDeleteTeam={handleDeleteTeam}
              onQueueTeam={handleQueueTeam}
            />
            <SuspendedPanel
              players={players}
              onToggleSuspend={handleToggleSuspendPlayer}
              loading={loadingPlayers}
            />
          </aside>
        )}

        {!isAdmin && currentPlayer && (
          <aside>
            {playersError && (
              <p className="text-sm text-red-600 mb-3">{playersError}</p>
            )}

            <PlayerPanel
              player={currentPlayer}
              myRequest={myRequest}
              players={players}
              onRequestPresent={handleRequestPresent}
              onCancelRequest={handleCancelRequest}
              onMarkAbsent={handleTogglePresent}
              onRequestCreateTeam={handleRequestCreateTeam}
              onRequestJoinTeam={handleRequestJoinTeam}
              onLeaveTeam={handleLeaveTeamSelf}
            />
          </aside>
        )}

        {editingProfile && currentPlayer && (
  <EditProfileModal
    player={currentPlayer}
    onClose={() => setEditingProfile(false)}
    onSaved={(updated) => {
      setPlayers((prev) => prev.map((p) => (p.id === updated.id ? updated : p)));
      setSessionState((s) => ({ ...s, name: updated.name }));
    }}
  />
)}
      </div>
    </main>
  );
}